namespace Test;

public class TestTopMovers
{
    public static IEnumerable<object[]> TopMoversData()
    {
        yield return [228.5m, 232.6m, JsonHistOneDay()];
        yield return [228.5m, 232.5m, JsonHistFiveDays()];
        yield return [228.5m, 237.9m, JsonHistMonth()];

    }

    [Theory]
    [MemberData(nameof(TopMoversData))]
    public void TopMoversTest(decimal firstValue, decimal lastValue, string jsonData)
    {
        string ticker = "NOVO-B.CO";
        decimal currentValue = 229m;
        List<ValuePoint> values = JsonSerializer.Deserialize<List<ValuePoint>>(jsonData);
        TimeRange t = TimeRange.OneDay;
        var novo = new StockViewModel()
        {
            HistoricalValues = values,
            Amount = 1,
            TimeRange = t,
            CurrentExchangeRate = 1,
        };

        var sorted = values.OrderByDescending(v => v.Date).ToList();
        Assert.Equal(Math.Round(firstValue, 2), Math.Round((decimal)sorted.First().Value, 2));
        Assert.Equal(Math.Round(lastValue, 2), Math.Round((decimal)sorted.Last().Value, 2));
    }


